import { useState } from 'react';

function price(from: string, through: string, part: string) {
  const first = Date.parse(from + 'T00:00:00Z');
  const last = Date.parse(through + 'T00:00:00Z');
  const days: { date: string; label: string; hours: number }[] = [];
  if (!Number.isFinite(first) || !Number.isFinite(last) || last < first || last - first > 365 * 86400000) return days;
  for (let t = first; t <= last; t += 86400000) {
    const date = new Date(t);
    const iso = date.toISOString().slice(0, 10);
    const holiday = ['2026-12-25', '2027-01-01'].includes(iso);
    const weekend = [5, 6].includes(date.getUTCDay());
    days.push({ date: iso, label: holiday ? 'Holiday excluded' : weekend ? 'Weekend excluded' : 'Working',
      hours: holiday || weekend ? 0 : part === 'Full' ? 8 : 4 });
  }
  return days;
}

export default function LiveQuotingComposer() {
  const [from, setFrom] = useState('2026-12-23');
  const [through, setThrough] = useState('2026-12-28');
  const [part, setPart] = useState('Full');
  const [available, setAvailable] = useState(120);
  const [submitted, setSubmitted] = useState(false);
  const days = price(from, through, part);
  const total = days.reduce((sum, d) => sum + d.hours, 0);
  const overlap = from <= '2026-12-30' && through >= '2026-12-28' && days.length > 0;
  const valid = total > 0 && total <= available && !submitted;

  return <form className="grid min-w-0 gap-3 p-3 text-start text-sm" onSubmit={event => {
    event.preventDefault();
    if (valid) { setAvailable(available - total); setSubmitted(true); }
  }}>
    <div className="grid gap-2 sm:grid-cols-3">
      <label className="grid min-w-0 gap-1 font-semibold">From<input className="w-full min-w-0 rounded-sm border bg-transparent p-2 font-normal" type="date" value={from} onChange={e => { setFrom(e.target.value); setSubmitted(false); }} /></label>
      <label className="grid min-w-0 gap-1 font-semibold">Through<input className="w-full min-w-0 rounded-sm border bg-transparent p-2 font-normal" type="date" value={through} onChange={e => { setThrough(e.target.value); setSubmitted(false); }} /></label>
      <label className="grid min-w-0 gap-1 font-semibold">Part of day<select className="w-full min-w-0 rounded-sm border bg-transparent p-2 font-normal" value={part} onChange={e => { setPart(e.target.value); setSubmitted(false); }}><option>Full</option><option>AM</option><option>PM</option></select></label>
    </div>
    <div className="max-h-56 overflow-auto" tabIndex={0} role="region" aria-label="Quote breakdown"><table className="w-full"><thead><tr>{['Date','Price basis','Hours'].map(h => <th key={h} className="border-b px-1 py-1.5 text-start">{h}</th>)}</tr></thead>
      <tbody>{days.map(d => <tr key={d.date}><td className="border-b px-1 py-1.5 text-start">{d.date}</td><td className="border-b px-1 py-1.5 text-start">
        <span className={'inline-flex items-center gap-1 rounded-sm border px-1.5 py-0.5 text-xs ' + (d.hours ? 'border-solid bg-emerald-100 text-emerald-950' : 'border-dashed')}><span aria-hidden="true">{d.hours ? '✓' : '−'}</span>{d.label}</span>
      </td><td className="border-b px-1 py-1.5 text-start">{d.hours}</td></tr>)}</tbody></table></div>
    {overlap && <p>Team overlap · Jordan Okafor is on leave December 28–30.</p>}
    <output>{total}h quoted · {available}h available</output>
    {!total && <p>Select a working date range of up to one year.</p>}
    {total > available && !submitted && <p>Insufficient balance.</p>}
    <button type="submit" className="w-fit rounded-sm border px-3 py-2 font-semibold disabled:opacity-50" disabled={!valid}>Reserve hours</button>
    {submitted && <p role="status">{total}h reserved.</p>}
  </form>;
}
